chains = {
  "push-up": "incline-push-up>knee-push-up>push-up>diamond-push-up>archer-push-up",
  "pull-up": "doorframe-row>inverted-row>negative-pull-up>band-assisted-pull-up>pull-up",
  "pistol-squat": "bodyweight-squat>split-squat>bulgarian-split-squat>pistol-squat",
  "pike-push-up": "pike-push-up>wall-handstand-push-up",
  "hollow-hold": "dead-bug>plank>hollow-hold",
  "hanging-leg-raise": "hanging-knee-raise>hanging-leg-raise",
}

out = []
for r in rows:
    (id_, name, pattern, equipment, any_of, primary, secondary, diff, bw, rest, kind, load, uni, avoid, cues, mistakes) = r
    e = {"id": id_, "name": name, "pattern": pattern, "equipment": equipment, "primary": primary, "secondary": secondary,
         "difficulty": diff, "bwFactor": bw, "restType": rest, "kind": kind, "loadType": load, "cues": cues, "mistakes": mistakes}
    if any_of: e["anyOf"] = any_of
    if uni: e["unilateral"] = True
    if avoid: e["avoid"] = avoid
    if kind == T: e["timed"] = True
    if id_ in chains: e["progression"] = chains[id_]
    out.append(e)

ids = [e["id"] for e in out]
assert len(ids) == len(set(ids)), "duplicate ids"
p = pathlib.Path(__file__).resolve().parent.parent / "src" / "data" / "exercises.json"
p.write_text(json.dumps(out, indent=1, ensure_ascii=False) + "\n")
print(f"wrote {len(out)} exercises → {p}")
